/* AIVIC_FUNCTION_BUNDLE_START owner=validateResourceAllocation exports=validateResourceAllocation */
const __aivicBundle_22_validateResourceAllocation = (() => {
  interface ValidateResourceAllocationInput {
    projectId: string;
    projectName: string;
    tasks: Array<{
      taskId: string;
      taskName: string;
      requiredStaff: number;
      requiredBudget: number;
      requiredHours: number;
    }>;
    availableResources: {
      totalAvailableStaff: number;
      totalAvailableBudget: number;
      totalAvailableHours: number;
    };
  }
  
  interface ValidateResourceAllocationResult {
    isResourceSufficient: boolean;
    warnings: string[];
    resourceShortages: {
      staffShortage: number;
      budgetShortage: number;
      hoursShortage: number;
    };
    report: {
      totalRequiredStaff: number;
      totalRequiredBudget: number;
      totalRequiredHours: number;
      totalAvailableStaff: number;
      totalAvailableBudget: number;
      totalAvailableHours: number;
      staffUtilizationRate: number;
      budgetUtilizationRate: number;
      hoursUtilizationRate: number;
    };
    status: "warning" | "success";
  }
  
   function validateResourceAllocation(
    input: ValidateResourceAllocationInput
  ): ValidateResourceAllocationResult {
    // Validate required inputs
    if (!String(input.projectId).trim()) {
      throw new Error("projectId is required");
    }
    if (!String(input.projectName).trim()) {
      throw new Error("projectName is required");
    }
  
    const { tasks, availableResources } = input;
  
    // Calculate total required resources from all tasks
    const totalRequiredStaff = tasks.reduce((sum, task) => sum + task.requiredStaff, 0);
    const totalRequiredBudget = tasks.reduce((sum, task) => sum + task.requiredBudget, 0);
    const totalRequiredHours = tasks.reduce((sum, task) => sum + task.requiredHours, 0);
  
    // Extract available resources
    const totalAvailableStaff = availableResources.totalAvailableStaff;
    const totalAvailableBudget = availableResources.totalAvailableBudget;
    const totalAvailableHours = availableResources.totalAvailableHours;
  
    // Calculate shortages
    const staffShortage = Math.max(0, totalRequiredStaff - totalAvailableStaff);
    const budgetShortage = Math.max(0, totalRequiredBudget - totalAvailableBudget);
    const hoursShortage = Math.max(0, totalRequiredHours - totalAvailableHours);
  
    // Determine if resources are sufficient
    const isResourceSufficient =
      staffShortage === 0 && budgetShortage === 0 && hoursShortage === 0;
  
    // Generate warnings for shortages
    const warnings: string[] = [];
    if (staffShortage > 0) {
      warnings.push(`人員不足: ${staffShortage}人が不足しています`);
    }
    if (budgetShortage > 0) {
      warnings.push(`予算不足: ${budgetShortage}円が不足しています`);
    }
    if (hoursShortage > 0) {
      warnings.push(`時間不足: ${hoursShortage}時間が不足しています`);
    }
  
    // Calculate utilization rates (available / required, rounded to 4 decimal places)
    const staffUtilizationRate =
      totalRequiredStaff > 0
        ? Math.round((totalAvailableStaff / totalRequiredStaff) * 10000) / 10000
        : 0;
    const budgetUtilizationRate =
      totalRequiredBudget > 0
        ? Math.round((totalAvailableBudget / totalRequiredBudget) * 10000) / 10000
        : 0;
    const hoursUtilizationRate =
      totalRequiredHours > 0
        ? Math.round((totalAvailableHours / totalRequiredHours) * 10000) / 10000
        : 0;
  
    return {
      isResourceSufficient,
      warnings,
      resourceShortages: {
        staffShortage,
        budgetShortage,
        hoursShortage,
      },
      report: {
        totalRequiredStaff,
        totalRequiredBudget,
        totalRequiredHours,
        totalAvailableStaff,
        totalAvailableBudget,
        totalAvailableHours,
        staffUtilizationRate,
        budgetUtilizationRate,
        hoursUtilizationRate,
      },
      status: isResourceSufficient ? "success" : "warning",
    };
  }
  return { validateResourceAllocation };
})();
export const validateResourceAllocation = __aivicBundle_22_validateResourceAllocation.validateResourceAllocation;
/* AIVIC_FUNCTION_BUNDLE_END owner=validateResourceAllocation */

