/* AIVIC_FUNCTION_BUNDLE_START owner=calculatePriorityScores exports=calculatePriorityScores */
const __aivicBundle_38_calculatePriorityScores = (() => {
  interface CalculatePriorityScoresInput {
    issues: Array<{
      issue_id: string;
      title: string;
      businessValueScore: number;
      technicalDifficultyScore: number;
      userImpactScore: number;
    }>;
    scoreCriteria: {
      businessValueWeight?: number;
      technicalDifficultyWeight?: number;
      userImpactWeight?: number;
    };
  }
  
  interface CalculatePriorityScoresOutput {
    issue_id: string;
    title: string;
    priorityScore: number;
    rank: number;
  }
  
   function calculatePriorityScores(
    input: CalculatePriorityScoresInput
  ): CalculatePriorityScoresOutput[] {
    const { issues, scoreCriteria } = input;
  
    // Validate scoreCriteria completeness
    if (
      scoreCriteria.businessValueWeight === undefined ||
      scoreCriteria.technicalDifficultyWeight === undefined ||
      scoreCriteria.userImpactWeight === undefined
    ) {
      throw new Error('スコアリング基準が不完全です。すべての重み付け値を指定してください。');
    }
  
    // Validate weights sum to 1.0
    const weightSum =
      scoreCriteria.businessValueWeight +
      scoreCriteria.technicalDifficultyWeight +
      scoreCriteria.userImpactWeight;
  
    const tolerance = 1e-9;
    if (Math.abs(weightSum - 1.0) > tolerance) {
      throw new Error(
        `重み付け値の合計が1である必要があります。現在の合計: ${weightSum}`
      );
    }
  
    // Validate individual scores are in range [0, 10]
    for (const issue of issues) {
      if (
        issue.businessValueScore < 0 ||
        issue.businessValueScore > 10 ||
        issue.technicalDifficultyScore < 0 ||
        issue.technicalDifficultyScore > 10 ||
        issue.userImpactScore < 0 ||
        issue.userImpactScore > 10
      ) {
        throw new Error(
          `スコアは0から10の範囲内である必要があります。issue_id: ${issue.issue_id}`
        );
      }
    }
  
    // Calculate priority scores
    const scoredIssues = issues.map((issue) => {
      // Formula: businessValue * weight + (10 - technicalDifficulty) * weight + userImpact * weight
      const priorityScore =
        issue.businessValueScore * scoreCriteria.businessValueWeight +
        (10 - issue.technicalDifficultyScore) *
          scoreCriteria.technicalDifficultyWeight +
        issue.userImpactScore * scoreCriteria.userImpactWeight;
  
      return {
        issue_id: issue.issue_id,
        title: issue.title,
        priorityScore,
      };
    });
  
    // Sort by priority score descending
    scoredIssues.sort((a, b) => b.priorityScore - a.priorityScore);
  
    // Assign ranks (1 = highest priority)
    const result: CalculatePriorityScoresOutput[] = scoredIssues.map(
      (item, index) => ({
        issue_id: item.issue_id,
        title: item.title,
        priorityScore: item.priorityScore,
        rank: index + 1,
      })
    );
  
    return result;
  }
  return { calculatePriorityScores };
})();
export const calculatePriorityScores = __aivicBundle_38_calculatePriorityScores.calculatePriorityScores;
/* AIVIC_FUNCTION_BUNDLE_END owner=calculatePriorityScores */

